-- Kochbuch-Schema für SQLite, bewusst nah an Postgres.
-- Unterschiede und der Umzug (auch nach Neon) stehen in db/README.md.
-- Fremdschlüssel in SQLite erst mit PRAGMA foreign_keys = ON aktiv.
-- Das Pragma steht im Build-Skript, nicht hier: Postgres kennt es nicht.
--
-- Primärschlüssel sind INTEGER mit festen ids im Seed. In Postgres können
-- die Spalten später GENERATED BY DEFAULT AS IDENTITY werden; die Inserts
-- mit gesetzter id bleiben gültig.

CREATE TABLE shopping_categories (
  id INTEGER PRIMARY KEY,
  name TEXT NOT NULL UNIQUE,
  sort_order INTEGER NOT NULL UNIQUE
);

CREATE TABLE units (
  id INTEGER PRIMARY KEY,
  code TEXT NOT NULL UNIQUE,
  name TEXT NOT NULL,
  dimension TEXT NOT NULL CHECK (dimension IN ('mass', 'volume', 'count', 'qualitative')),
  -- Basis ist g, ml oder Stk. NULL, wenn die Einheit nicht allgemein umrechenbar ist.
  base_unit_code TEXT,
  factor_to_base REAL,
  CHECK (
    (factor_to_base IS NULL AND base_unit_code IS NULL)
    OR (factor_to_base IS NOT NULL AND factor_to_base > 0 AND base_unit_code IS NOT NULL)
  )
);

CREATE TABLE ingredients (
  id INTEGER PRIMARY KEY,
  name TEXT NOT NULL UNIQUE,
  category_id INTEGER NOT NULL REFERENCES shopping_categories (id),
  default_unit_id INTEGER REFERENCES units (id),
  -- 1 = Vorrat, den die Einkaufsliste auf Wunsch ausblendet (Salz, Mehl, Zucker).
  pantry_staple INTEGER NOT NULL DEFAULT 0 CHECK (pantry_staple IN (0, 1))
);

-- Produktbezogene Umrechnung, wo die Einheit allein nicht reicht
-- (1 Pkt. Vanillezucker = 8 g, 1 Pkt. Backpulver wäre etwas anderes).
CREATE TABLE ingredient_unit_conversions (
  ingredient_id INTEGER NOT NULL REFERENCES ingredients (id),
  unit_id INTEGER NOT NULL REFERENCES units (id),
  base_unit_code TEXT NOT NULL,
  factor_to_base REAL NOT NULL CHECK (factor_to_base > 0),
  note TEXT,
  PRIMARY KEY (ingredient_id, unit_id)
);

CREATE TABLE recipes (
  id INTEGER PRIMARY KEY,
  slug TEXT NOT NULL UNIQUE,
  title TEXT NOT NULL,
  servings INTEGER NOT NULL CHECK (servings > 0),
  servings_label TEXT NOT NULL DEFAULT 'Personen',
  prep_minutes INTEGER CHECK (prep_minutes IS NULL OR prep_minutes >= 0),
  cook_minutes INTEGER CHECK (cook_minutes IS NULL OR cook_minutes >= 0),
  source TEXT,
  notes TEXT
);

CREATE TABLE tags (
  id INTEGER PRIMARY KEY,
  name TEXT NOT NULL UNIQUE
);

CREATE TABLE recipe_tags (
  recipe_id INTEGER NOT NULL REFERENCES recipes (id),
  tag_id INTEGER NOT NULL REFERENCES tags (id),
  PRIMARY KEY (recipe_id, tag_id)
);

CREATE TABLE recipe_ingredients (
  id INTEGER PRIMARY KEY,
  recipe_id INTEGER NOT NULL REFERENCES recipes (id),
  ingredient_id INTEGER NOT NULL REFERENCES ingredients (id),
  -- NULL, wenn sich die Angabe nicht als Zahl fassen lässt. Dann trägt amount_text die Zeile.
  quantity REAL,
  unit_id INTEGER REFERENCES units (id),
  amount_text TEXT,
  preparation TEXT,
  ingredient_group TEXT NOT NULL,
  -- Kaufmerkmal, das die Summe trennt, z. B. 'Gr. M' bei Eiern.
  variant TEXT,
  optional INTEGER NOT NULL DEFAULT 0 CHECK (optional IN (0, 1)),
  sort_order INTEGER NOT NULL,
  CHECK (quantity IS NULL OR quantity >= 0),
  CHECK (quantity IS NULL OR unit_id IS NOT NULL),
  CHECK (quantity IS NOT NULL OR amount_text IS NOT NULL)
);

CREATE TABLE meal_plans (
  id INTEGER PRIMARY KEY,
  name TEXT NOT NULL,
  starts_on DATE NOT NULL,
  ends_on DATE NOT NULL,
  notes TEXT,
  CHECK (ends_on >= starts_on)
);

CREATE TABLE meal_plan_entries (
  id INTEGER PRIMARY KEY,
  meal_plan_id INTEGER NOT NULL REFERENCES meal_plans (id),
  plan_date DATE NOT NULL,
  -- Übliche Werte: Frühstück, Mittagessen, Abendessen, Jause, Nachspeise.
  meal_slot TEXT NOT NULL,
  recipe_id INTEGER NOT NULL REFERENCES recipes (id),
  servings INTEGER NOT NULL CHECK (servings > 0),
  notes TEXT
);

CREATE INDEX idx_ingredients_category ON ingredients (category_id);
CREATE INDEX idx_recipe_ingredients_recipe ON recipe_ingredients (recipe_id);
CREATE INDEX idx_recipe_ingredients_ingredient ON recipe_ingredients (ingredient_id);
CREATE INDEX idx_meal_plan_entries_date ON meal_plan_entries (plan_date);
CREATE INDEX idx_meal_plan_entries_recipe ON meal_plan_entries (recipe_id);

-- Eine Zeile pro Zutat eines Planeintrags, schon auf die gewünschten Portionen skaliert.
-- Die Summierung über den Zeitraum macht db/shopping_list.sql, damit das Datum
-- vor dem GROUP BY gefiltert werden kann.
CREATE VIEW v_meal_plan_lines AS
SELECT
  e.id AS entry_id,
  p.id AS meal_plan_id,
  p.name AS meal_plan_name,
  e.plan_date AS plan_date,
  e.meal_slot AS meal_slot,
  e.servings AS planned_servings,
  r.id AS recipe_id,
  r.slug AS recipe_slug,
  r.title AS recipe_title,
  r.servings AS recipe_servings,
  (CAST(e.servings AS REAL) / CAST(r.servings AS REAL)) AS servings_scale,
  i.id AS ingredient_id,
  i.name AS ingredient_name,
  i.pantry_staple AS pantry_staple,
  c.sort_order AS category_sort,
  c.name AS category_name,
  ri.ingredient_group AS ingredient_group,
  ri.variant AS variant,
  ri.preparation AS preparation,
  ri.amount_text AS amount_text,
  ri.optional AS optional,
  ri.sort_order AS sort_order,
  ri.quantity AS quantity,
  u.code AS unit_code,
  CASE
    WHEN ri.quantity IS NULL THEN NULL
    ELSE ri.quantity * (CAST(e.servings AS REAL) / CAST(r.servings AS REAL))
  END AS scaled_quantity,
  COALESCE(iuc.base_unit_code, u.base_unit_code) AS base_unit_code,
  CASE
    WHEN ri.quantity IS NULL THEN NULL
    WHEN iuc.factor_to_base IS NOT NULL THEN
      ri.quantity * (CAST(e.servings AS REAL) / CAST(r.servings AS REAL)) * iuc.factor_to_base
    WHEN u.factor_to_base IS NOT NULL THEN
      ri.quantity * (CAST(e.servings AS REAL) / CAST(r.servings AS REAL)) * u.factor_to_base
    ELSE NULL
  END AS scaled_base_quantity
FROM meal_plan_entries AS e
JOIN meal_plans AS p ON p.id = e.meal_plan_id
JOIN recipes AS r ON r.id = e.recipe_id
JOIN recipe_ingredients AS ri ON ri.recipe_id = r.id
JOIN ingredients AS i ON i.id = ri.ingredient_id
JOIN shopping_categories AS c ON c.id = i.category_id
LEFT JOIN units AS u ON u.id = ri.unit_id
LEFT JOIN ingredient_unit_conversions AS iuc
  ON iuc.ingredient_id = ri.ingredient_id
 AND iuc.unit_id = ri.unit_id;
